from typing import *
import heapq


def kheapsort(arr, k):
    if len(arr) <= k:
        return sorted(arr)

    heap = arr[:k]
    heapq.heapify(heap)

    for x in arr[k:]:
        heapq.heappushpop(heap, x)

    while heap:
        heapq.heappop(heap)

    return sorted(arr)
